	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/cp/predictions", wrapper.ListCpPredictions)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/fleet", wrapper.ListFleet)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/health", wrapper.GetHealth)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/history", wrapper.ListHistory)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/keys", wrapper.ListKeys)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/keys", wrapper.CreateKey)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/keys/{key_id}", wrapper.RevokeKey)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/metrics", wrapper.GetMetrics)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/metro/live", wrapper.GetMetroLive)
